# Mock classes for testing
class Patient:
    def __init__(self, age, conditions, severities):
        self.age = age
        self.conditions = conditions  # list of strings
        self.severities = severities  # list of severity ints/floats

    def get_total_conditions(self):
        return len(self.conditions)

    def get_average_severity(self):
        if not self.severities:
            return 0
        return sum(self.severities) / len(self.severities)

class Hospital:
    def __init__(self, patients, records):
        # patients: {id: Patient}
        # records: {id: list(dict)}
        self.patients = patients
        self.records = records

    def get_patient(self, patient_id):
