    def get_recent_records(self, patient_id, days):
        # simulates records from last `days`
        return self.records.get(patient_id, [])

# Utility for abnormal vitals
def record_has_abnormal_vitals(records):
    # Suppose, record contains: {'vitals': {'heart_rate': 110, 'bp': '140/100'}}
    # We define abnormal if heart_rate > 100 or bp systolic > 130
    for rec in records:
        vitals = rec.get('vitals', {})
        if vitals.get('heart_rate', 80) > 100:
            return True
        try:
            systolic = int(vitals.get('bp', '120/80').split('/')[0])
            if systolic > 130:
                return True
        except Exception:
            pass
    return False

def patient_risk_score(hospital, patient_id):
    '''
    Create a function called patient_risk_score that takes a Hospital object and patient_id. Calculate risk score using formula: (patient.age / 100 * 30) + (patient.get_total_conditions() * 5 * 25/100) + (patient.get_average_severity() * 10 * 25/100) + (20 if recent records have abnormal vitals else 0). Use hospital.get_patient(patient_id) and hospital.get_recent_records(patient_id, 90). Returns: float between 0.0 and 100.0.
    '''
    patient = hospital.get_patient(patient_id)
    if patient is None:
        return 0.0
    records = hospital.get_recent_records(patient_id, 90)

    risk = 0.0
    risk += (patient.age / 100 * 30)
    risk += (patient.get_total_conditions() * 5 * 0.25)
    risk += (patient.get_average_severity() * 10 * 0.25)
    if record_has_abnormal_vitals(records):
        risk += 20
    return max(0.0, min(risk, 100.0))

