        # returns all records for patient_id within last 'days'
        return self.vitals_records.get(patient_id, [])

# Helper to simulate abnormal vitals
def are_vitals_abnormal(vitals, abnormal_range):
    for vital in vitals:
        for k, v in vital.items():
            if k in abnormal_range:
                low, high = abnormal_range[k]
                if not (low <= v <= high):
                    return True
    return False

# For testing, a minimal patient_risk_score implementation according to formula, 
# with abnormal_range definition for vitals (e.g., heart_rate, bp_systolic, bp_diastolic).

def patient_risk_score(hospital, patient_id):
    patient = hospital.get_patient(patient_id)
    age_score = (patient.age / 100) * 30
    conditions_score = patient.get_total_conditions() * 5 * 25 / 100
    severity_score = patient.get_average_severity() * 10 * 25 / 100

    # Define abnormal ranges for test: heart_rate 60-100, bp_systolic 90-120, bp_diastolic 60-80
    abnormal_range = {'heart_rate': (60, 100), 'bp_systolic': (90, 120), 'bp_diastolic': (60, 80)}
    recent_records = hospital.get_recent_records(patient_id, 90)
    if recent_records and are_vitals_abnormal(recent_records, abnormal_range):
        vitals_score = 20
    else:
        vitals_score = 0

    score = age_score + conditions_score + severity_score + vitals_score
    return max(0.0, min(score, 100.0))

