def calculate_simple_gpa(university, student_id):
    '''
    Calculate a basic 0.0-4.0 GPA for a student.
    For each enrollment, multiply the grade points by course credits.
    Sum total grade points and credits and return the weighted GPA.
    '''
    total_points = 0.0
    total_credits = 0

    enrollments = university.get_student_enrollments(student_id)
    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        if course:
            grade_points = enrollment.get_grade_points()
            credits = course.credits
            total_points += grade_points * credits
            total_credits += credits

    if total_credits == 0:
        return 0.0

    return total_points / total_credits


# Test cases for calculate_simple_gpa(university, student_id)
# Mock objects and helper classes are needed since the function depends on other classes.

class MockCourse:
    def __init__(self, code, credits):
        self.code = code
        self.credits = credits

class MockEnrollment:
    def __init__(self, course_code, grade_points):
        self.course_code = course_code
        self._grade_points = grade_points
    def get_grade_points(self):
        return self._grade_points

class MockUniversity:
    def __init__(self, students_enrollments, courses):
        # students_enrollments: dict mapping student_id to list of Enrollments
        # courses: dict mapping course_code to Course
        self.students_enrollments = students_enrollments
        self.courses = courses

    def get_student_enrollments(self, student_id):
        return self.students_enrollments.get(student_id, [])

    def get_course(self, course_code):
        return self.courses.get(course_code)

def calculate_simple_gpa(university, student_id):
    '''
    See prompt description.
    '''
    enrollments = university.get_student_enrollments(student_id)
    total_points = 0.0
    total_credits = 0
    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        if course is None or course.credits == 0:
            continue
        grade_points = enrollment.get_grade_points()
        total_points += grade_points * course.credits
        total_credits += course.credits
    if total_credits == 0:
        return 0.0
    return round(total_points / total_credits, 2)

# Test case 1: Student with two enrollments, perfect scores, normal credits
courses = {
    "MATH101": MockCourse("MATH101", 3),
    "ENG102": MockCourse("ENG102", 4)
}
enrollments = {
    "stu1": [
        MockEnrollment("MATH101", 4.0),
        MockEnrollment("ENG102", 4.0)
    ]
}
university = MockUniversity(enrollments, courses)
assert calculate_simple_gpa(university, "stu1") == 4.0, "Student with two perfect grades"

# Test case 2: Student with mixed grades and different credit values
courses = {
    "SCI201": MockCourse("SCI201", 3),
    "HIST202": MockCourse("HIST202", 2),
    "ART203": MockCourse("ART203", 1)
}
enrollments = {
