        MockEnrollment("SCI201", 3.0),  # 9.0
        MockEnrollment("HIST202", 2.0), # 4.0
        MockEnrollment("ART203", 4.0)   # 4.0
    ]
}
university = MockUniversity(enrollments, courses)
# total_points = 9.0 + 4.0 + 4.0 = 17.0, total_credits = 3 + 2 + 1 = 6
assert calculate_simple_gpa(university, "stu2") == round(17.0/6,2), "Student with mixed grades and credits"

# Test case 3: Student with no enrollments
enrollments = {
    "stu3": []
}
university = MockUniversity(enrollments, courses)
assert calculate_simple_gpa(university, "stu3") == 0.0, "Student with no enrollments"

# Test case 4: Student with an enrollment in a course with zero credits (should be ignored)
courses = {
    "PE204": MockCourse("PE204", 0),
    "MUSIC205": MockCourse("MUSIC205", 1)
}
enrollments = {
    "stu4": [
        MockEnrollment("PE204", 3.0),      # credits = 0, ignored
        MockEnrollment("MUSIC205", 2.0)    # credits = 1, used
    ]
}
university = MockUniversity(enrollments, courses)
assert calculate_simple_gpa(university, "stu4") == 2.0, "Student with zero credit course enrollments"

# Test case 5: GPA value gets rounded to 2 decimal places
courses = {
    "A": MockCourse("A", 2),
    "B": MockCourse("B", 3)
}
enrollments = {
    "stu5": [
        MockEnrollment("A", 2.33),   # 4.66
