university = MockUniversity(enrollments, courses)
# total_points = 4.66 + 11.01 = 15.67; total_credits = 2 + 3 = 5; GPA=15.67/5=3.134 ... should round to 3.13
assert calculate_simple_gpa(university, "stu5") == 3.13, "Rounding of GPA to two decimal places"

# Test case 6: One of the enrollments is for a course not present in university.courses
courses = {
