    with open('performance_reviews.csv', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            # Make a shallow copy and convert rating to float
            new_row = dict(row)
            # Convert numeric columns to int/float
            for col in ['technical_score', 'communication_score', 'teamwork_score', 'leadership_score']:
                if col in new_row:
                    new_row[col] = int(new_row[col])
            if 'overall_rating' in new_row:
                new_row['overall_rating'] = float(new_row['overall_rating'])
            rows.append(new_row)

    if employee_id is not None:
        # Search for the employee row
        match = None
        for r in rows:
            if r['employee_id'] == employee_id:
                match = r
                break
        if not match:
            return None  # or raise Exception, depending on requirements
        if report_type == 'summary':
            return {
                'employee_id': match['employee_id'],
                'overall_rating': match['overall_rating'],
                'goals_status': match['goals_status'],
            }
        elif report_type == 'detailed':
            return dict(match)  # already cast correct types above
        else:
            raise ValueError(f'Unknown report_type for single employee: {report_type}')
    else:
        if report_type == 'department':
            from collections import defaultdict
            group = defaultdict(list)    # department: [overall_ratings]
            for r in rows:
                dept = r['department']
                group[dept].append(r['overall_rating'])
            result = {}
            for dept, ratings in group.items():
                if ratings:
                    avg = sum(ratings) / len(ratings)
                else:
                    avg = 0.0
                result[dept] = {'avg_rating': avg, 'count': len(ratings)}
            return result
        else:
            raise ValueError(f'Unknown report_type for group: {report_type}')

